static std::vector<wstring>selectFiles(HWND owner,bool pdf){std::vector<wstring>v;std::vector<wchar_t>b(65536);OPENFILENAMEW o={};o.lStructSize=sizeof(o);o.hwndOwner=owner;o.lpstrFilter=GalaxyFileFilter(pdf?L"PDF·그림\0*.pdf;*.png;*.jpg;*.jpeg;*.webp\0모든 파일\0*.*\0":L"그림 파일\0*.png;*.jpg;*.jpeg;*.webp;*.bmp\0모든 파일\0*.*\0");o.lpstrFile=b.data();o.nMaxFile=(DWORD)b.size();o.Flags=OFN_FILEMUSTEXIST|OFN_ALLOWMULTISELECT|OFN_EXPLORER|OFN_NOCHANGEDIR;if(!GetOpenFileNameW(&o))return v;wstring first=b.data();wchar_t*n=b.data()+first.size()+1;if(!*n)v.push_back(first);else while(*n){v.push_back(first+L"\\"+n);n+=wcslen(n)+1;}return v;}
