static void addFiles(int p,std::vector<wstring>v){bool first=files[p].empty();for(auto&s:v)files[p].push_back(s);rebuild(p);if(p==1){if(first&&!v.empty()){bool allPdf=std::all_of(v.begin(),v.end(),isPdf);SendMessageW(GetDlgItem(panels[1],MODE),CB_SETCURSEL,allPdf?(v.size()>1?0:2):3,0);}layoutPdfWorkspace();}if(!v.empty()){SendMessageW(GetDlgItem(panels[p],FILELIST),LB_SETCURSEL,0,0);auto file=files[p][0];if(p==1&&isPdf(file))choosePdfSource(file);else showPreview(p,file);if(p==0||p==4)preparePreview(p,file);}}


static void reorder(int p,int direction,bool remove){int n=(int)SendMessageW(GetDlgItem(panels[p],FILELIST),LB_GETCURSEL,0,0);if(n<0||n>=(int)files[p].size())return;if(remove)files[p].erase(files[p].begin()+n);else if(n+direction>=0&&n+direction<(int)files[p].size())std::swap(files[p][n],files[p][n+direction]);rebuild(p);SendMessageW(GetDlgItem(panels[p],FILELIST),LB_SETCURSEL,std::max(0,n+direction),0);}
static void pdfAction(int id){HWND p=panels[1];if(files[1].empty()){say(p,L"먼저 PDF 또는 그림을 선택하세요.");return;}int mode=index(p,MODE);wstring path=pdfSource.empty()?files[1][0]:pdfSource,range=text(p,PAGE_RANGE_ID);if(id==ANNOTATE){int n=pdfPage();if(!n){say(p,L"먼저 페이지를 클릭하세요. Ctrl 또는 Shift로 여러 페이지를 선택할 수 있습니다.");return;}run({{"op","pdf_render"},{"path",u8(path)},{"pages",std::to_string(n)},{"dpi",144},{"format","png"},{"output_dir",u8(cacheDir)}},1,3);return;}if(id==EXTRACT){auto selected=selectedPages();if(selected.empty()){say(p,L"먼저 페이지를 클릭하세요. Ctrl 또는 Shift로 여러 페이지를 선택할 수 있습니다.");return;}J r=J::object();for(int n:selected)if(rotations[n])r[std::to_string(n)]=rotations[n];run({{"op","pdf_manage"},{"path",u8(path)},{"page_order",selected},{"rotations",r},{"output_dir",u8(outputDir)}},1);return;}
J job={{"output_dir",u8(outputDir)}};if(mode==0){job["op"]="pdf_merge";job["paths"]=paths(files[1]);}else if(mode==1){std::vector<int>selected;if(range.empty()){selected=selectedPages();if(selected.empty())selected=pages;}else if(!PageOrder::parseRange(range,pdfOriginalCount,selected)){say(p,L"범위를 1-3,5처럼 입력하고 원본 페이지 번호를 확인하세요.");return;}if(selected.empty()){say(p,L"남길 페이지가 없습니다. PDF를 다시 선택하거나 페이지를 남겨 주세요.");return;}job["op"]="pdf_manage";job["path"]=u8(path);job["page_order"]=selected;J r=J::object();for(int n:selected)if(rotations[n])r[std::to_string(n)]=rotations[n];job["rotations"]=r;}else if(mode==2){if(pages.empty()){say(p,L"남길 페이지가 없습니다. PDF를 다시 선택하거나 페이지를 남겨 주세요.");return;}job["op"]="pdf_manage";job["path"]=u8(path);job["page_order"]=pages;J r=J::object();for(auto v:rotations)r[std::to_string(v.first)]=v.second;job["rotations"]=r;}else if(mode==3){job["op"]="images_pdf";job["paths"]=paths(files[1]);job["page_size"]=index(p,PAPERSIZE)==0?"a4":"image";job["orientation"]=index(p,ORIENTATION)==0?"portrait":"landscape";job["margin_mm"]=number(p,MARGIN,10);}else{if(range.empty())for(int n:selectedPages()){if(!range.empty())range+=L",";range+=std::to_wstring(n);}job["op"]="pdf_render";job["path"]=u8(path);job["pages"]=u8(range);job["format"]=index(p,FORMAT)==0?"png":"jpg";int d[]={96,144,200,300};job["dpi"]=d[std::max(0,index(p,DPIBOX))];}run(job,1);}
static void copyText(const wstring&s){if(!OpenClipboard(host))return;HGLOBAL h=GlobalAlloc(GMEM_MOVEABLE,(s.size()+1)*2);if(h){void*p=GlobalLock(h);if(p){memcpy(p,s.c_str(),(s.size()+1)*2);GlobalUnlock(h);EmptyClipboard();if(!SetClipboardData(CF_UNICODETEXT,h))GlobalFree(h);}else GlobalFree(h);}CloseClipboard();}
static void pasteCode(){if(ToolEngineBusy()){say(panels[4],L"현재 작업을 마친 뒤 실행하세요.");return;}wchar_t temp[MAX_PATH],file[MAX_PATH];if(!GetTempPathW(MAX_PATH,temp)||!GetTempFileNameW(temp,L"GQR",0,file))return;wstring path=wstring(file)+L".png";DeleteFileW(file);if(!SaveClipboardImage(path)){say(panels[4],L"클립보드에 그림이 없습니다. 이미지 파일을 선택해 읽을 수 있습니다.");return;}if(!run({{"op","code_read"},{"path",u8(path)}},4,5))DeleteFileW(path.c_str());}

