static void recordTick(){if(recordStopPending&&GetTickCount64()-recordStopAt>5000&&Recording::Active())Recording::Stop();if(!recordControl)return;auto n=Recording::Elapsed()/1000;GalaxySetText(GetDlgItem(recordControl,RECORDPAUSE),Recording::Paused()?L"녹화 재개":L"일시정지");wstring s=wstring(GalaxyTr(Recording::Paused()?L"● 일시정지 ":L"● 녹화 중 "))+std::to_wstring(n/60)+L":"+(n%60<10?L"0":L"")+std::to_wstring(n%60)+GalaxyTr(L" · Ctrl+Shift+F10 중지");GalaxySetText(GetDlgItem(recordControl,RECORDLABEL),s.c_str());say(panels[3],s);}
