void ShowToolPage(int n){current=n;for(int i=0;i<6;i++)if(panels[i])ShowWindow(panels[i],i==n?SW_SHOW:SW_HIDE);if(n==5&&!phonePanel)phonePanel=OpenPhonePanel(inst,host);if(phonePanel)ShowWindow(phonePanel,n==5?SW_SHOW:SW_HIDE);I18NLocalizeTree(host);LayoutToolHub();}
void LayoutToolHub(){RECT r;GetClientRect(host,&r);for(auto p:panels)if(p)MoveWindow(p,0,S(40),r.right,r.bottom-S(40),TRUE);if(phonePanel)MoveWindow(phonePanel,0,S(42),r.right,r.bottom-S(42),TRUE);layoutPdfWorkspace();}
bool ToolEngineBusy(){return InterlockedCompareExchange(&busy,0,0)!=0;}
void ShutdownToolHub(){for(auto&s:cacheFiles)DeleteFileW(s.c_str());RemoveDirectoryW(cacheDir.c_str());Recording::WaitForFinish();ShutdownPhonePanel();if(font)DeleteObject(font);}
void ToolHubDrop(HDROP drop){if(ToolEngineBusy()){DragFinish(drop);return;}if(current!=0&&current!=1&&current!=4){DragFinish(drop);return;}SendMessageW(panels[current],WM_DROPFILES,(WPARAM)drop,0);}
void SubmitPdfOverlay(const wstring&pdf,int page,const wstring&overlay){run({{"op","pdf_annotate"},{"path",u8(pdf)},{"page",page},{"overlay_path",u8(overlay)},{"output_dir",u8(outputDir)}},1);}
bool HandleToolHubMessage(UINT m,WPARAM w,LPARAM l){if(m==Recording::StartedMessage){NativeAgent::RecordStarted(true);return true;}if(m==EngineDone){reply((Reply*)l);return true;}if(m==WM_HOTKEY&&w==701){requestRecordStop();return true;}if(m==WM_TIMER&&w==RecordTick){recordTick();return true;}if(m==Recording::FinishedMessage){std::unique_ptr<Recording::Result>r((Recording::Result*)l);Recording::ClearIndicator();bool shared=recordViaSharedHost;recordViaSharedHost=false;recordStopPending=false;NativeAgent::RecordFinished(r->ok,r->path);KillTimer(host,RecordTick);UnregisterHotKey(host,701);if(recordControl){DestroyWindow(recordControl);recordControl=nullptr;}if(shared)NativeAgent::OpenCategory("record");else{ShowWindow(host,SW_RESTORE);SetForegroundWindow(host);}if(r->ok){outputs[3]={r->path};say(panels[3],L"녹화 완료: "+r->path);}else{wchar_t c[80];swprintf(c,80,L"0x%08lx",(unsigned long)r->error);say(panels[3],L"녹화하지 못했습니다 ("+wstring(c)+L"). 저장 폴더, 회사 보안 정책 또는 Windows 미디어 기능을 확인하세요.");}return true;}return false;}

void ToolHubLanguageChanged(){pagesRebuild();layoutPdfWorkspace();if(recordControl){GalaxySetText(GetDlgItem(recordControl,RECORDSTOP),L"녹화 중지");recordTick();}}

bool ToolHubPaste(){if(current!=0&&current!=1)return false;HWND focus=GetFocus();wchar_t cls[64];GetClassNameW(focus,cls,64);if(!_wcsicmp(cls,L"Edit")&&!(GetWindowLongPtrW(focus,GWL_STYLE)&ES_READONLY))return false;if(ToolEngineBusy()){say(panels[current],L"현재 작업을 마친 뒤 실행하세요.");return true;}std::vector<wstring>incoming;if(OpenClipboard(host)){HDROP drop=(HDROP)GetClipboardData(CF_HDROP);if(drop){UINT count=DragQueryFileW(drop,0xffffffff,nullptr,0);for(UINT i=0;i<count;i++){UINT n=DragQueryFileW(drop,i,nullptr,0);wstring path(n+1,0);DragQueryFileW(drop,i,path.data(),n+1);path.resize(n);incoming.push_back(path);}}CloseClipboard();}if(!incoming.empty()){addFiles(current,incoming);return true;}wstring file=cacheDir+L"\\clipboard_"+std::to_wstring(GetTickCount64())+L".png";if(SaveClipboardImage(file)){cacheFiles.push_back(file);addFiles(current,{file});return true;}return false;}
